#!/usr/bin/env bash
# Generate digger.yml from the directory tree. Nobody lists regions by hand.
#
#   project   = every environments/<stage>/<leader>/<region>/terragrunt.hcl
#   name      = <layer>[-<stage>-<leader>|-<leader>][-<region>]  (only what is needed to be unique)
#   patterns  = the layer's *.tf, the instance dir, plus extras from layer.yaml
#   depends   = layer.yaml `depends_on` (layer names) resolved to the closest
#               instance of that layer: same stage/leader/region, else same
#               stage/leader, else same region; `layer@stage/leader[/region]`
#               pins an instance; project.yaml in an instance dir adds more.
#
# Usage: generate-inventory.sh [--check]   (--check fails if digger.yml is stale)
set -euo pipefail
cd "$(dirname "$0")/../../.."
ROOT=infra/terraform/layers

mapfile -t instances < <(find "$ROOT" -path '*/environments/*/terragrunt.hcl' | sort)

# instance record: category layer stage leader region dir
rec() { local d; d=$(dirname "$1"); local r=${d#"$ROOT"/}; IFS=/ read -r cat layer _ stage leader region <<<"$r"; echo "$cat $layer $stage $leader $region $d"; }
declare -a RECS; for i in "${instances[@]}"; do RECS+=("$(rec "$i")"); done

count_matching() { # layer stage leader -> how many regions this layer has under stage/leader
  local n=0 r l s ld
  for r in "${RECS[@]}"; do read -r _ l s ld _ _ <<<"$r"; [ "$l $s $ld" = "$1 $2 $3" ] && n=$((n+1)); done
  echo $n
}

name_of() { # layer stage leader region
  local layer=$1 stage=$2 leader=$3 region=$4 n="$1"
  if [ "$stage" != shared ]; then n="$n-$stage-$leader"
  elif [ "$leader" != "$layer" ] && [[ "$layer" != "$leader"* ]]; then n="$n-$leader"; fi
  [ "$(count_matching "$layer" "$stage" "$leader")" -gt 1 ] && n="$n-$region"
  echo "$n"
}

declare -A DIR STAGE LEADER REGION LAYER CAT
for r in "${RECS[@]}"; do
  read -r cat layer stage leader region dir <<<"$r"
  n=$(name_of "$layer" "$stage" "$leader" "$region")
  DIR[$n]=$dir; STAGE[$n]=$stage; LEADER[$n]=$leader; REGION[$n]=$region; LAYER[$n]=$layer; CAT[$n]=$cat
done

resolve() { # from-project dep-spec -> project names
  # Never cross tenants: same stage/leader first; otherwise only a *shared*
  # instance of the layer (same region preferred). prod never depends on nonprod.
  local from=$1 spec=$2 layer=${2%%@*} pin=""; [[ "$spec" == *@* ]] && pin=${spec#*@}
  local n inst same_inst=() same_tenant=() shared_region=() shared_any=()
  for n in $(printf '%s\n' "${!DIR[@]}" | sort); do
    [ "${LAYER[$n]}" = "$layer" ] || continue
    inst="${STAGE[$n]}/${LEADER[$n]}/${REGION[$n]}"
    if [ -n "$pin" ]; then [[ "$inst" == "$pin"* ]] && echo "$n"; continue; fi
    if [ "$inst" = "${STAGE[$from]}/${LEADER[$from]}/${REGION[$from]}" ]; then same_inst+=("$n")
    elif [ "${STAGE[$n]}/${LEADER[$n]}" = "${STAGE[$from]}/${LEADER[$from]}" ]; then same_tenant+=("$n")
    elif [ "${STAGE[$n]}" = shared ] && [ "${REGION[$n]}" = "${REGION[$from]}" ]; then shared_region+=("$n")
    elif [ "${STAGE[$n]}" = shared ]; then shared_any+=("$n"); fi
  done
  [ -n "$pin" ] && return 0
  if [ ${#same_inst[@]} -gt 0 ]; then printf '%s\n' "${same_inst[@]}"
  elif [ ${#same_tenant[@]} -gt 0 ]; then printf '%s\n' "${same_tenant[@]}"
  elif [ ${#shared_region[@]} -gt 0 ]; then printf '%s\n' "${shared_region[@]}"
  elif [ ${#shared_any[@]} -gt 0 ]; then printf '%s\n' "${shared_any[@]}"
  else echo "::warning::$from depends on layer '$layer' but no instance in its tenant or shared; skipped" >&2; fi
}

out=$(mktemp)
{
  echo "# GENERATED by .github/scripts/digger/generate-inventory.sh — do not edit."
  echo "# Add a region or layer by adding a terragrunt.hcl; declare dependencies in layer.yaml."
  echo "delete_prior_comments: true"
  echo "telemetry: false"
  echo
  echo "projects:"
  for n in $(printf '%s\n' "${!DIR[@]}" | sort); do
    dir=${DIR[$n]}; layer=${LAYER[$n]}; cat=${CAT[$n]}
    layer_dir="$ROOT/$cat/$layer"
    deps=(); extras=()
    if [ -f "$layer_dir/layer.yaml" ]; then
      mapfile -t d < <(yq -r '.depends_on // [] | .[]' "$layer_dir/layer.yaml"); deps+=("${d[@]}")
      mapfile -t e < <(yq -r '.include_patterns // [] | .[]' "$layer_dir/layer.yaml"); extras+=("${e[@]}")
    fi
    if [ -f "$dir/project.yaml" ]; then
      mapfile -t d < <(yq -r '.depends_on // [] | .[]' "$dir/project.yaml"); deps+=("${d[@]}")
    fi
    resolved=$(for s in "${deps[@]}"; do resolve "$n" "$s"; done | sort -u | grep -v "^$n$" || true)
    echo "  - name: $n"
    echo "    dir: $dir"
    echo "    workflow: default"
    echo "    terragrunt: true"
    echo "    drift_detection: true"
    if [ -n "$resolved" ]; then echo "    depends_on: [$(echo "$resolved" | sed 's/.*/"&"/' | paste -sd, - | sed 's/,/, /g')]"; fi
    echo "    include_patterns:"
    echo "      - \"$layer_dir/*.tf\""
    echo "      - \"$layer_dir/files/**\""
    echo "      - \"$dir/**\""
    for e in "${extras[@]}"; do echo "      - \"$e\""; done
  done
  echo
  echo "workflows:"
  echo "  default:"
  echo "    on_pull_request_pushed: [\"digger plan\"]"
  echo "    plan:"
  echo "      steps:"
  echo "        - run: terragrunt plan -out \"\$DIGGER_PLANFILE\""
  echo "    apply:"
  echo "      steps:"
  echo "        - run: terragrunt apply -auto-approve \"\$DIGGER_PLANFILE\""
} > "$out"

if [ "${1:-}" = --check ]; then
  if diff -u digger.yml "$out"; then echo "digger.yml is up to date"; else echo "::error::digger.yml is stale; run .github/scripts/digger/generate-inventory.sh"; exit 1; fi
else
  mv "$out" digger.yml; echo "wrote digger.yml ($(grep -c '^  - name:' digger.yml) projects)"
fi
